using System;using Ashfall.Core;using Ashfall.Modules.HealthStates;
namespace Ashfall.Integration.Playable.HandsWeapons {
 public sealed partial class R23RoundState {
  sealed class LocalMatchHealthWorld:IHealthWorld {readonly R23RoundState owner;internal LocalMatchHealthWorld(R23RoundState value){owner=value;}public double Now{get{return owner.localMatchClock;}}public bool InMatch{get{return owner.localMatchHealth&&!owner.localMatchConfiguring&&!owner.resettingPractice;}}public bool TeamChangesAllowed{get{return false;}}public bool TryGetPose(string id,out RescuePose pose){return owner.TryGetPose(id,out pose);}}
  bool localMatchHealth,localMatchConfiguring;double localMatchClock;int localMatchStartingHealth=100,localMatchStartingShield=100;float localMatchDamage=1;bool localMatchRespawn;
  public bool LocalMatchHealthConfigured{get{return localMatchHealth||PlayerHealthViewBound;}}public bool LocalMatchAlive{get{var state=PlayerHealthState;return state!=null&&state.Life==LifeState.Alive&&state.Health>0;}}
  public void ConfigureLocalMatchHealth(string mode,int teams,int team,int startingHealth,int startingShield,double protection,double downedSeconds,double respawnDelay,double clock,float damageMultiplier){if((mode!="revive"&&mode!="respawn")||teams<0||teams>8||(teams==0?team!=-1:team<0||team>=teams)||startingHealth<1||startingHealth>100||startingShield<0||startingShield>100||double.IsNaN(clock)||double.IsInfinity(clock)||clock<0||float.IsNaN(damageMultiplier)||float.IsInfinity(damageMultiplier)||damageMultiplier<0||damageMultiplier>6)throw new ArgumentException("Actual local source match health rules required");if(PlayerHealthViewBound)throw new InvalidOperationException("Unbind authoritative Health before local configuration");localMatchClock=clock;localMatchStartingHealth=startingHealth;localMatchStartingShield=startingShield;localMatchDamage=damageMultiplier;localMatchRespawn=mode=="respawn";localMatchHealth=true;localMatchConfiguring=true;health=new HealthService("r23-player",0,teams,localMatchRespawn,this,new LocalMatchHealthWorld(this),query,downedSeconds,respawnDelay,protection);try{if(!health.Register(Command(),"player",team,false).Accepted)throw new InvalidOperationException("Actual local player health registration failed");var p=health.Read("player");if(!health.Spawn(Command(),"player",p.Revision,startingHealth,startingShield).Accepted)throw new InvalidOperationException("Actual starting health/protection refused");int npcTeam=teams==0?-1:teams>1?(team+1)%teams:team;foreach(var id in targets)if(!health.Register(Command(),id,npcTeam,false).Accepted)throw new InvalidOperationException("Existing practice Health actor refused");}finally{localMatchConfiguring=false;}health.DrainTransitions();SuspendActiveWeapon();}
  public void AdvanceLocalMatchHealth(double clock){if(PlayerHealthViewBound||!localMatchHealth)return;if(double.IsNaN(clock)||double.IsInfinity(clock)||clock<localMatchClock)throw new ArgumentOutOfRangeException("clock");localMatchClock=clock;health.Advance(Command());health.DrainTransitions();}
  public bool ApplyLocalMatchDamage(float amount,bool direct,string cause){if(playerHealthView!=null)return playerHealthView.ApplyDamage(amount,direct,cause);if(!localMatchHealth||!LocalMatchAlive||float.IsNaN(amount)||float.IsInfinity(amount)||amount<=0)return false;if(cause!="zone")amount*=localMatchDamage;if(amount<=0)return false;var before=health.Read("player");float shield=direct?0:Math.Min(before.Shield,amount),loss=Math.Min(before.Health,amount-shield);var command=Command();var result=health.ApplyDamage(command,command.CommandId,"player",before.Revision,loss,shield,true);health.DrainTransitions();return result.Result.Accepted&&(result.Snapshot.Health<before.Health||result.Snapshot.Shield<before.Shield);}
  public bool ApplyLocalMatchFall(){if(playerHealthView!=null)return playerHealthView.ApplyFall();if(!localMatchHealth)return false;var before=health.Read("player");var result=health.ApplyMatchFallDeath(Command(),"player",before.Revision);health.DrainTransitions();return result.Accepted;}
  public bool TryRespawnLocalMatch(){if(PlayerHealthViewBound||!localMatchHealth||!localMatchRespawn)return false;var before=health.Read("player");if(before.Life!=LifeState.Dead||localMatchClock<before.RespawnAt)return false;var r=health.Spawn(Command(),"player",before.Revision,localMatchStartingHealth,localMatchStartingShield);health.DrainTransitions();return r.Accepted;}
  // Fresh exploration-map life without resetting weapon owners, ammo or inventories.
  public bool ResetMapVitals(){
   if(PlayerHealthViewBound||localMatchHealth||retiredRound||health==null)return false;
   var before=health.Read("player");if(before==null)return false;
   bool previous=resettingPractice;resettingPractice=true;
   try{var result=health.Spawn(Command(),"player",before.Revision,100,100);health.DrainTransitions();return result.Accepted;}
   finally{resettingPractice=previous;}
  }
  public void EndLocalMatchHealth(){if(PlayerHealthViewBound||!localMatchHealth)return;localMatchHealth=false;health=new HealthService("r23-player",0,0,false,this,this,query,60,5,0);health.Register(Command(),"player",-1,false);foreach(var id in targets)health.Register(Command(),id,-1,false);health.DrainTransitions();SetLocalMatchInfiniteAmmo(false);}
  public void SetLocalMatchInfiniteAmmo(bool enabled){foreach(var pair in reserves){var policy=pair.Value as R24MatchAmmoReserve;if(policy!=null)policy.SetInfinite(enabled);}}
  public int ReadStoredAmmoReserveFamily(string family){Ashfall.Modules.WeaponHandling.IRevisionedAmmoReserve value;if(!reserves.TryGetValue(family,out value))return 0;var policy=value as R24MatchAmmoReserve;return policy==null?value.Available:policy.StoredAvailable;}
 }
}
